questions.question:
다음 SQL 수행 결과로 옳은 것은?

CREATE TABLE TAB (
    col1 INT PRIMARY KEY,
    col2 INT IDENTITY(1,1)
);
INSERT INTO TAB (col1) VALUES(-1);
INSERT INTO TAB VALUES(0,1);
INSERT INTO TAB VALUES(1,2);

SELECT COUNT(*) FROM TAB;

다음 SQL 문의 실행 결과로 가장 적절한 것은?

SELECT REGEXP_REPLACE('2025-12-25', '^(\d{4})-(\d{2})-(\d{2})$', '\3\2\1') AS RESULT
FROM DUAL;

다음은 Oracle 데이터베이스에서 뷰를 생성하고 삭제하는 작업을 순서대로 수행한 것이다. 아래 SQL을 모두 수행했을 때 결과에 대한 설명으로 옳은 것은?

CREATE TABLE EMP (
    EMPNO NUMBER,
    ENAME VARCHAR2(20),
    DEPTNO NUMBER
);

CREATE VIEW V_EMP
AS
SELECT EMPNO, ENAME, DEPTNO
FROM EMP;

CREATE VIEW V_EMP10
AS
SELECT EMPNO, ENAME
FROM V_EMP
WHERE DEPTNO = 10;

DROP VIEW V_EMP RESTRICT;
